require_once __DIR__.'/../includes/auth.php';require_parent_guest();$errors=[];$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=(string)($_POST['password']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||$password!==($_POST['confirm_password']??''))$errors[]='Please enter a valid name, email and matching password of at least 8 characters.';if(!$errors){$db=db();$s=$db->prepare('INSERT INTO parents(full_name,email,password_hash,status) VALUES(?,?,?,\'active\')');if(!$s){error_log('Parent registration prepare failed: '.$db->error);$errors[]='Parent registration is temporarily unavailable. Please try again shortly.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$s->bind_param('sss',$name,$email,$hash);if($s->execute()){flash('success','Parent account created. Please log in.');redirect('parent/login.php');}$errorNumber=$s->errno;$errorText=$s->error;$s->close();error_log('Parent registration insert failed: '.$errorNumber.' '.$errorText);$errors[]=$errorNumber===1062?'This email already has a parent account.':'Account could not be created. Please try again.';}}}
$pageTitle='Parent registration';include __DIR__.'/../includes/header.php';?>
